style.css:
@-moz-document domain("chess.com") {
/* Светлые клетки — Блок Травы */
  .board .square.light, 
  .board-layout-chessboard .square.light,
  [class*="square-"].light,
  .board-custom-background .light {
    background-image: url('https://images.images-medium.net/p/rNf39vU.jpeg') !important;
    background-size: cover !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
  }

  /* Темные клетки — Блок Камня */
  .board .square.dark, 
  .board-layout-chessboard .square.dark,
  [class*="square-"].dark,
  .board-custom-background .dark {
    background-image: url('https://images.images-medium.net/p/vHq0A28.jpeg') !important;
    background-size: cover !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
  }
}
